"""Revision 8: 19 newly written themes with rests for environmental voices.

Each has eight A bars, eight B bars and four bridge bars (repeated once).
All note sequences are written here; no shared melody generation or snapping.
"""
from score_model import section

def part(chords,notes):
    rows=notes.strip().split('|')
    symbols=chords.split()
    if len(rows)==4: rows=rows*2; symbols=symbols*2
    return section(' '.join(symbols),'\n'.join(rows))

def score(title,key,bpm,a,b,c,mode='major',form='abacba'):
    return dict(title=title,key=key,bpm=bpm,beats=4,meter='4/4',mode=mode,form=form,
                a=part(*a),b=part(*b),c=part(*c))

